#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>

int main() {
    std::string streamData = "100 Alice 150.25\n200 Bob -30.50\n";
    std::istringstream stream(streamData);

    int account;
    std::string name;
    double balance;

    while (stream >> account >> name >> balance) {
        std::cout << account << " " << name << " " 
                  << std::fixed << std::setprecision(2) << balance << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>

int main() {
    std::string mockStdin = 
        "100 Jones 24.98\n"
        "200 Doe 345.67\n"
        "300 White 0.00\n"
        "400 Stone -42.16\n"
        "500 Rich 224.62\n";

    std::istringstream cinStream(mockStdin);
    std::ostringstream fileOut;

    unsigned int account;
    std::string name;
    double balance;

    while (cinStream >> account >> name >> balance) {
        fileOut << account << " " << name << " " 
                << std::fixed << std::setprecision(2) << balance << "\n";
    }

    std::cout << fileOut.str();
    return 0;
}
